<script setup>
import { ref, watch, onMounted } from 'vue'
import { useRouter } from 'vue-router'
import { useCity } from '../composables/useCity'
import { houseApi } from '../api/house'
import { guideApi } from '../api/modules'
import ArrowIcon from './ArrowIcon.vue'
import SiteFooter from './SiteFooter.vue'
import { useScrollScenes } from '../composables/useScrollScenes'
import { isReducedMotion } from '../composables/motionPreference'
const router = useRouter(), root = ref(null), story = ref(null), keyword = ref(''), activeScene = ref(0)
const sceneScrollLock = ref(0)
const { currentCity } = useCity()
let houseVersion = 0
const houses = ref([]), guides = ref([]), houseLoading = ref(true), guideLoading = ref(true), houseError = ref(false), guideError = ref(false)
const scenes = [{ title:'说出需求，找到合适的家', subtitle:'把预算、通勤和喜欢的生活，一起考虑。' }, { title:'一张图片，也能成为起点', subtitle:'从喜欢的房间，发现相似的居住空间。' }, { title:'看懂合同，心里更有底', subtitle:'了解条款与政策，少一点签字前的疑惑。' }]
const extractList = response => { const data = response?.data; return Array.isArray(data) ? data : Array.isArray(data?.list) ? data.list : Array.isArray(data?.records) ? data.records : [] }
async function loadHouses() { const version=++houseVersion; houseLoading.value=true; houseError.value=false; try { const r=await houseApi.list({city:currentCity.value,status:'APPROVED',page:1,size:6}); if(version===houseVersion) houses.value=extractList(r) } catch { if(version===houseVersion) houseError.value=true } finally { if(version===houseVersion) houseLoading.value=false } }
async function loadGuides() { guideLoading.value = true; guideError.value = false; try { guides.value = extractList(await guideApi.list({ page:1, size:3 })) } catch { guideError.value = true } finally { guideLoading.value = false } }
function search() { router.push({ path:'/houses', query:{ city:currentCity.value, ...(keyword.value.trim() ? { keyword:keyword.value.trim() } : {}) } }) }
function scrollTo(id) { document.getElementById(id)?.scrollIntoView({ behavior:isReducedMotion() ? 'instant' : 'smooth' }) }
function selectScene(index) {
  activeScene.value = index
  if (window.innerWidth > 800 && !isReducedMotion() && story.value) {
    sceneScrollLock.value = Date.now() + 1000
    const header = parseFloat(getComputedStyle(document.documentElement).getPropertyValue('--header-height')) || 84
    const travel = story.value.offsetHeight - window.innerHeight + header
    window.scrollTo({ top:story.value.getBoundingClientRect().top + window.scrollY - header + travel * ((index + .4) / 3), behavior:'smooth' })
  }
}
function sceneKeydown(event, index) { if (['ArrowDown','ArrowRight','ArrowUp','ArrowLeft','Home','End'].includes(event.key)) { event.preventDefault(); const target = event.key === 'Home' ? 0 : event.key === 'End' ? 2 : (index + (['ArrowDown','ArrowRight'].includes(event.key) ? 1 : 2)) % 3; selectScene(target); document.getElementById(`scene-tab-${target}`)?.focus({ preventScroll:true }) } }
function imageError(event) { const fallback = '/house-images/uns_1600210492486-724fe5c67fb0.jpg'; if (!event.target.src.endsWith(fallback)) event.target.src = fallback }
function formatPrice(price) { return Number(price || 0).toLocaleString('zh-CN') }
watch(currentCity, loadHouses)
useScrollScenes(root, story, activeScene, sceneScrollLock)
onMounted(() => { loadHouses(); loadGuides() })
</script>

